-- =====================================================================
-- SIGAF · Carga · 035 · Fecha REAL de pago de TODO lo pagado (N_AP_IMSS_4002, pagos 02/01–30/10/2026)
-- Fecha: 30/10/2026
-- 12 partes del 4002 (Pagado X Fecha Pago X UN), 30,062 renglones sin huecos de fechas. Se tomaron los
-- comprobantes con línea en la UI 010102 (HGZ 2) o 019001 (pasivo central de pedidos): 8,294.
-- Para cada factura de SIGAF con ese CR (no anulada ni devuelta):
--   · fecha_pago = fecha real de pago (la más reciente si el comprobante tuvo varios pagos)
--   · Gasto reflejado si seguía en trámite (solo avanza)
--   · pedido / recepción: solo se llenan si están vacíos
-- Completa lo que el 4007 (032) no cubría: compra emergente, subrogados, víveres, fondo fijo, etc.
-- Cómo: SQL Editor → Run (el archivo es grande, tarda unos segundos). Muestra cuántas facturas cambiaron.
-- =====================================================================
drop table if exists t4002;
create temp table t4002 (cr text primary key, fecha_pago date, pedido text, recepcion text);

with upd as (
  update facturas f set
    fecha_pago       = t.fecha_pago,
    estatus_general  = case when f.estatus_general in ('enviada_ooad','en_tramite_ooad') then 'gasto_reflejado' else f.estatus_general end,
    numero_pedido    = coalesce(nullif(btrim(f.numero_pedido), ''), t.pedido),
    numero_recepcion = coalesce(nullif(btrim(f.numero_recepcion), ''), t.recepcion)
  from t4002 t
  where ltrim(btrim(f.cr_contrarecibo), '0') = t.cr
    and f.anulada = false and f.estatus_general <> 'devuelta_proveedor'
    and (f.fecha_pago is distinct from t.fecha_pago
         or f.estatus_general in ('enviada_ooad','en_tramite_ooad')
         or (t.pedido is not null and nullif(btrim(f.numero_pedido), '') is null))
  returning f.id, f.estatus_general
)
select count(*) as facturas_actualizadas,
       count(*) filter (where estatus_general = 'gasto_reflejado') as quedaron_pagadas
from upd;